template <class T, class = void>
struct HasName : std::false_type
{
};

template <class T>
struct HasName<T, decltype((void)T::name)> : std::true_type
{
};

template <class T, bool = HasName<T>::value>
struct GetName;

template <class T>
struct GetName<T, false>
{
    static carb::cpp::string_view name() noexcept
    {
        return omni::otel::parse<T>();
    }
};

template <class T>
struct GetName<T, true>
{
    static carb::cpp::string_view name() noexcept
    {
        return carb::cpp::string_view(T::name);
    }
};

template <class MeterType>
IMeter* getMeter()
{
    IObservability* observability = carb::getCachedInterface<IObservability>();
    if (!observability)
        return nullptr;
    return observability->getMeterByHash(
        omni::otel::type_hash<MeterType>::value, GetName<MeterType>::name(), MeterType::version, MeterType::schemaUrl);
}

template <class MeterType, class InstrumentType, class ValueType>
struct CounterBase
{
    static ICounter<ValueType>* getInstrument()
    {
        if (IMeter* m = getMeter<MeterType>())
            return m->getCounterByHash<ValueType>(omni::otel::type_hash<InstrumentType>::value,
                                                  GetName<InstrumentType>::name(), InstrumentType::description,
                                                  InstrumentType::unit);
        return nullptr;
    }

    template <class T>
    static void addArr(T value, const Attribute attributes[], std::size_t attributeCount) noexcept
    {
        if (ICounter<ValueType>* counter = getInstrument())
            counter->add(value, attributes, attributeCount);
    }

    template <class T, class... A>
    static void add(T value, A&&... a) noexcept
    {
        if (ICounter<ValueType>* counter = getInstrument())
            counter->add(value, std::forward<A>(a)...);
    }

    template <class T>
    static void add(T value, std::initializer_list<Attribute> attributes) noexcept
    {
        if (ICounter<ValueType>* counter = getInstrument())
            counter->add(value, attributes);
    }
};

