/** Base class for meter type definitions.
 *
 *  Derive from this class to define a meter type with optional version and schema URL. The derived
 *  type will be used as a compile-time identifier for the meter.
 *
 *  Naming: The meter name is automatically deduced from the type name (including namespace). For
 *  example, a type `MyNamespace::ServiceMeter` will have the meter name `"MyNamespace/ServiceMeter"`.
 *  This automatic naming can be overridden by defining a static `name` member in the derived type.
 *
 *  The base Meter type provides default empty values for version and schemaUrl members. Derived
 *  types can provide definitions with the same names to hide the base definitions, or omit them to
 *  use the defaults.
 *
 *  The `version` member represents the version of your library or component that emits the
 *  metrics.
 *
 *  The `schemaUrl` member helps observability backends understand the structure and
 *  conventions used in your telemetry data, enabling consumers to interpret them correctly.
 *  An example of such standardization is the metric with name `http.server.duration`,
 *  which should be a histogram that uses seconds as the unit of measurement, and should
 *  include attributes `http.method`, `http.status_code`, `http.route`, `server.address`,
 *  and `server.port`.
 *
 *  @code
 *  struct MyServiceMeter : omni::observability::Meter
 *  {
 *      constexpr static char version[] = "1.2.0";
 *      constexpr static char schemaUrl[] = "https://opentelemetry.io/schemas/1.21.0";
 *  };
 *
 *  struct SimpleServiceMeter : omni::observability::Meter
 *  {
 *  };
 *
 *  struct CustomNamedMeter : omni::observability::Meter
 *  {
 *      constexpr static char name[] = "my.custom.meter";
 *  };
 *  @endcode
 */
struct Meter
{
    constexpr static char version[] = "";
    constexpr static char schemaUrl[] = "";
};

/** Base class for instrument type definitions.
 *
 *  Derive from this class to define an instrument type with required description and optional unit.
 *  The derived type will be used as a compile-time identifier for the instrument.
 *
 *  Naming: The instrument name is automatically deduced from the type name (including namespace).
 *  For example, a type `MyNamespace::RequestCounter` will have the instrument name
 *  `"MyNamespace/RequestCounter"`. This automatic naming can be overridden by defining a static
 *  `name` member in the derived type.
 *
 *  The base Instrument type provides a default empty value for the unit member. Derived types are
 *  required to define a description member, and can optionally define a unit member and/or name
 *  member to override the defaults.
 *
 *  @code
 *  struct RequestCounter : omni::observability::Instrument
 *  {
 *      constexpr static char description[] = "Total number of requests";
 *      constexpr static char unit[] = "requests";
 *  };
 *
 *  struct ErrorCounter : omni::observability::Instrument
 *  {
 *      constexpr static char description[] = "Number of errors encountered";
 *  };
 *
 *  struct CustomNamedCounter : omni::observability::Instrument
 *  {
 *      constexpr static char name[] = "my.custom.counter.name";
 *      constexpr static char description[] = "Counter with custom name";
 *  };
 *  @endcode
 *
 *  @remark The description member is required and must be defined in derived types. The unit member
 *          defaults to empty but can be overridden. The name member is optional; if not provided,
 *          the instrument name is automatically deduced from the type name. Units should follow the
 *          UCUM standard: https://unitsofmeasure.org/ucum.html
 */
struct Instrument
{
    constexpr static char unit[] = "";
};

/** Type-based counter instrument.
 *
 *  A counter is a monotonic instrument that measures values that only increase over time,
 *  such as request counts, bytes processed, or errors encountered. Counter values cannot
 *  decrease and are reset to zero when the application restarts.
 *
 *  This counter uses the observability abstraction layer, which can be backed by different
 *  telemetry implementations (e.g., OpenTelemetry) depending on configuration.
 *
 *  @tparam MeterType A type derived from omni::observability::Meter that identifies the meter.
 *  @tparam InstrumentType A type derived from omni::observability::Instrument that identifies this counter.
 *  @tparam ValueType The numeric type for counter values (default: std::uint64_t).
 *
 *  @code
 *  struct MyServiceMeter : omni::observability::Meter {};
 *  struct RequestCounter : omni::observability::Instrument
 *  {
 *      constexpr static char description[] = "Total HTTP requests processed";
 *      constexpr static char unit[] = "requests";
 *  };
 *
 *  using HttpRequestCounter = omni::observability::Counter<MyServiceMeter, RequestCounter>;
 *  HttpRequestCounter::add(1, {{"method", "GET"}, {"status", "200"}});
 *  @endcode
 */
template <class MeterType, class InstrumentType, class ValueType = std::uint64_t>
struct Counter : detail::CounterBase<MeterType, InstrumentType, ValueType>
{
};

/** Type-based up/down counter instrument.
 *
 *  An up/down counter measures values that can go up or down over time,
 *  such as active connections, queue size, or memory usage. Unlike regular counters,
 *  up/down counters can have negative deltas and their values can decrease.
 *
 *  This counter uses the observability abstraction layer, which can be backed by different
 *  telemetry implementations (e.g., OpenTelemetry) depending on configuration.
 *
 *  @tparam MeterType A type derived from omni::observability::Meter that identifies the meter.
 *  @tparam InstrumentType A type derived from omni::observability::Instrument that identifies this counter.
 *  @tparam ValueType The numeric type for counter values (default: std::int64_t).
 *
 *  @code
 *  struct MyServiceMeter : omni::observability::Meter {};
 *  struct ActiveConnections : omni::observability::Instrument
 *  {
 *      constexpr static char description[] = "Number of active client connections";
 *      constexpr static char unit[] = "connections";
 *  };
 *
 *  using ConnectionCounter = omni::observability::UpDownCounter<MyServiceMeter, ActiveConnections>;
 *  ConnectionCounter::add(1);   // Connection opened
 *  ConnectionCounter::add(-1);  // Connection closed
 *  @endcode
 */
template <class MeterType, class InstrumentType, class ValueType = std::int64_t>
struct UpDownCounter : detail::UpDownCounterBase<MeterType, InstrumentType, ValueType>
{
};

/** Type-based histogram instrument.
 *
 *  A histogram measures the distribution of values over time, such as request latencies,
 *  response sizes, or processing times. It provides statistical summaries including
 *  count, sum, and configurable buckets for percentile analysis.
 *
 *  This histogram uses the observability abstraction layer, which can be backed by different
 *  telemetry implementations (e.g., OpenTelemetry) depending on configuration.
 *
 *  @tparam MeterType A type derived from omni::observability::Meter that identifies the meter.
 *  @tparam InstrumentType A type derived from omni::observability::Instrument that identifies this histogram.
 *  @tparam ValueType The numeric type for histogram values (default: std::uint64_t).
 *
 *  @code
 *  struct MyServiceMeter : omni::observability::Meter {};
 *  struct RequestLatency : omni::observability::Instrument
 *  {
 *      constexpr static char description[] = "HTTP request processing time";
 *      constexpr static char unit[] = "ms";
 *  };
 *
 *  using LatencyHistogram = omni::observability::Histogram<MyServiceMeter, RequestLatency>;
 *  LatencyHistogram::record(42.5, {{"endpoint", "/api/users"}});
 *  @endcode
 */
template <class MeterType, class InstrumentType, class ValueType = std::uint64_t>
struct Histogram : detail::HistogramBase<MeterType, InstrumentType, ValueType>
{
};

/** Type-based gauge instrument.
 *
 *  A gauge records instantaneous values that can go up or down, such as current temperature,
 *  current memory usage, or current queue size. Unlike counters which accumulate values over time,
 *  gauges represent the current state at the time of recording.
 *
 *  This gauge uses the observability abstraction layer, which can be backed by different
 *  telemetry implementations (e.g., OpenTelemetry) depending on configuration.
 *
 *  @tparam MeterType A type derived from omni::observability::Meter that identifies the meter.
 *  @tparam InstrumentType A type derived from omni::observability::Instrument that identifies this gauge.
 *  @tparam ValueType The numeric type for gauge values (default: std::int64_t).
 *
 *  @code
 *  struct MyServiceMeter : omni::observability::Meter {};
 *  struct CurrentTemperature : omni::observability::Instrument
 *  {
 *      constexpr static char description[] = "Current room temperature";
 *      constexpr static char unit[] = "celsius";
 *  };
 *
 *  using TemperatureGauge = omni::observability::Gauge<MyServiceMeter, CurrentTemperature, double>;
 *  TemperatureGauge::record(22.5, {{"room", "server"}});
 *  @endcode
 */
template <class MeterType, class InstrumentType, class ValueType = std::int64_t>
struct Gauge : detail::GaugeBase<MeterType, InstrumentType, ValueType>
{
};

